-- Estimated daily history (Tmax, Tmin, rain) for 1 Jan 2011 through 26 Dec 2020,
-- generated by rwcwx.estimated.generate from Pulgas Ridge PUGC1 (see rwcwx/estimated/conversions.py).
-- Creates a new table only; no existing table is touched. Idempotent.
-- Do NOT apply this file or load rows as part of a dry run. Apply only with
-- explicit approval, after reviewing the generated CSV:
--   mysql wx < data/migrations/20261112_daily_estimated.sql
--   mysql wx < path/to/daily_estimated_v2.sql
-- Until the table exists, requests without est=1 are unchanged, and requests
-- with est=1 simply have no estimated days to merge (or can use RWC_ESTIMATED_CSV).
CREATE TABLE IF NOT EXISTS `daily_estimated` (
  `d` date NOT NULL COMMENT 'local calendar date',
  `var` enum('temp','rain') NOT NULL COMMENT 'same names as avg_extreme',
  `type` enum('max','min','total') NOT NULL COMMENT 'Tmax, Tmin, or rain total',
  `val` float NOT NULL COMMENT 'native units: temp °C, rain inches (same as avg_extreme)',
  `source` varchar(16) NOT NULL COMMENT 'pugc1',
  `method` varchar(32) NOT NULL COMMENT 'v2-linear or v2-ratio',
  `version` varchar(16) NOT NULL DEFAULT 'v2' COMMENT 'conversion set; see rwcwx.estimated.conversions',
  `confidence` char(1) NOT NULL COMMENT 'A = Pulgas Ridge primary source',
  `raw_val` float DEFAULT NULL COMMENT 'source value in native units before conversion (temp °C, rain inches)',
  `t_mod` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'UTC, when this row was last written',
  PRIMARY KEY (`d`, `var`, `type`, `version`),
  KEY `var_type_d` (`var`, `type`, `d`)
) ENGINE=InnoDB
DEFAULT CHARSET utf8mb4
COMMENT 'Estimated daily Tmax, Tmin and rain before the station record';
